package org.zhixiaoce.aperture;
import org.json.*;
import java.util.*;

public final class CinemaRevisionTest {
    static int checks;static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
    static void rejects(Run run)throws Exception{boolean rejected=false;try{run.go();}catch(Exception expected){rejected=true;}check(rejected,"invalid input accepted");}interface Run{void go()throws Exception;}
    public static void main(String[] args)throws Exception{
        String media="https://media.example.invalid/movie.mp4";JSONObject item=new JSONObject().put("id","film").put("title","合成影片").put("cover","https://images.example.invalid/poster.jpg").put("plot","来源提供的简介").put("year","2026").put("genre","纪录片").put("duration","96分钟").put("rating","8.2").put("ratingSource","来源评分").put("episodes",new JSONArray().put(new JSONObject().put("title","正片").put("url",media).put("cover","https://images.example.invalid/episode.jpg")));
        JSONObject live=new JSONObject().put("id","tv").put("title","测试频道").put("type","live").put("channels",new JSONArray().put(new JSONObject().put("id","news").put("title","CCTV1 综合").put("group","测试").put("number",51).put("epgId","one").put("logo","https://images.example.invalid/logo.jpg").put("urls",new JSONArray().put(media))));
        JSONObject pack=new JSONObject().put("format","kaishi.resource-pack").put("version",1).put("id","org.example.test").put("revision",1).put("title","测试资源").put("resources",new JSONArray().put(new JSONObject().put("id","list").put("type","collection").put("title","测试片单").put("section","movies").put("items",new JSONArray().put(item))).put(live).put(new JSONObject().put("id","guide").put("type","epg").put("title","测试节目单").put("url","https://guide.example.invalid/guide.xml.gz")));
        CinemaCatalog.Config config=CinemaCatalog.config(pack.toString(),null,false);CinemaCatalog.Item film=CinemaResourcePack.page(config.sites.get(0),1,null,null).items.get(0);check(film.poster.endsWith("poster.jpg")&&film.summary.equals("来源提供的简介")&&film.rating.equals("8.2")&&film.duration.equals("96分钟"),"metadata aliases reach the catalogue");check(config.lives.get(0).channels.get(0).number==51&&config.lives.get(0).channels.get(0).epgId.equals("one"),"channel identity lost");
        CinemaCatalog.Config restored=CinemaCatalog.config(config.json(),null,false);check(restored.epgs.size()==1&&restored.lives.get(0).channels.get(0).number==51,"XMLTV/channel number cache lost");check(CinemaResourcePack.page(restored.sites.get(0),1,null,null).items.get(0).poster.equals(film.poster),"poster lost at save/read boundary");check(!CinemaResourcePack.shouldApply(config,CinemaCatalog.config(pack.toString(),null,false)),"same pack must not append");
        JSONObject bad=new JSONObject(pack.toString());bad.getJSONArray("resources").getJSONObject(0).getJSONArray("items").getJSONObject(0).put("cover","http://images.example.invalid/poster.jpg");rejects(()->CinemaCatalog.config(bad.toString(),null,false));JSONObject conflict=new JSONObject(pack.toString());conflict.getJSONArray("resources").getJSONObject(0).getJSONArray("items").getJSONObject(0).put("metadata",new JSONObject().put("poster","https://other.example.invalid/a.jpg"));rejects(()->CinemaCatalog.config(conflict.toString(),null,false));
        JSONObject repeat=new JSONObject(pack.toString());JSONObject channel=repeat.getJSONArray("resources").getJSONObject(1).getJSONArray("channels").getJSONObject(0);repeat.getJSONArray("resources").getJSONObject(1).getJSONArray("channels").put(new JSONObject(channel.toString()).put("id","another"));rejects(()->CinemaCatalog.config(repeat.toString(),null,false));
        List<CinemaCatalog.Live> duplicates=new ArrayList<>(config.lives);duplicates.add(restored.lives.get(0));check(CinemaLiveSources.visible(duplicates).size()==1&&duplicates.size()==2,"identical display sources collapse without deleting stored IDs");CinemaCatalog.Channel other=new CinemaCatalog.Channel("CCTV1 综合","测试",Arrays.asList("https://different.example.invalid/live.m3u8"));duplicates.add(new CinemaCatalog.Live("测试频道","",Arrays.asList(other)));check(CinemaLiveSources.visible(duplicates).size()==2,"different playback source must remain selectable");
        long now=CinemaEpg.instant("20261027200000 +0800");String xml="<tv><channel id='one'><display-name>CCTV1</display-name></channel><programme channel='one' start='20261027193000 +0800' stop='20261027203000 +0800'><title>合成当前节目</title></programme><programme channel='one' start='20261027203000 +0800' stop='20261027213000 +0800'><title>合成下一节目</title></programme><programme channel='one' start='20261028200000 +0800' stop='20261028210000 +0800'><title>合成明日节目</title></programme></tv>";
        CinemaEpg guide=CinemaEpg.read(xml,now);check(guide.nowNext(config.lives.get(0).channels.get(0),now).contains("合成下一节目"),"explicit channel ID must resolve now/next");CinemaCatalog.Channel fallback=new CinemaCatalog.Channel("CCTV1 综合","测试",Arrays.asList(media));check(guide.programmes(fallback).size()==3,"display-name mapping and tomorrow retained");check(CinemaEpg.instant("20261027120000 +0000")==now,"XMLTV timezone offset");rejects(()->CinemaEpg.read("<!DOCTYPE tv [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><tv>&x;</tv>",now));rejects(()->CinemaEpg.read("<not-tv/>",now));rejects(()->CinemaEpg.instant("20261340000000 +0800"));
        List<CinemaCatalog.Channel> m3u=CinemaCatalog.playlist("#EXTM3U\n#EXTINF:-1 tvg-id=\"one\" tvg-chno=\"51\" tvg-logo=\"https://images.example.invalid/logo.jpg\",CCTV1\n"+media,null,false,Collections.emptyMap());check(m3u.get(0).number==51&&m3u.get(0).epgId.equals("one"),"M3U channel number and EPG ID");
        check(PlaybackTimeline.step(0,120000,1,0)==10000,"single seek step");check(PlaybackTimeline.step(10000,120000,-1,0)==0,"seek clamp to start");check(PlaybackTimeline.step(115000,120000,1,0)==120000,"seek clamp to end");check(PlaybackTimeline.step(10000,120000,1,5)==30000&&PlaybackTimeline.step(10000,120000,1,12)==50000,"held key 2x/4x acceleration");check(PlaybackTimeline.time(3661000).equals("1:01:01")&&PlaybackTimeline.time(-1).equals("00:00"),"timeline formatting");CinemaCatalog.Channel auto=new CinemaCatalog.Channel("未编号频道","测试",Arrays.asList(media));CinemaCatalog.Channel explicit=new CinemaCatalog.Channel("已编号频道","测试",Arrays.asList(media));explicit.number=1;int[] assigned=CinemaChannelNumbers.assign(Arrays.asList(auto,explicit));check(assigned[0]==2&&assigned[1]==1,"implicit channel numbers must not shadow an explicit number");
        System.out.println(checks+" native revision assertions passed");
    }
}
